public int[] TopKFrequent(int[] nums, int k) {
    var count = new Dictionary<int, int>();
    foreach (int x in nums) count[x] = count.GetValueOrDefault(x) + 1;
    var buckets = new List<int>[nums.Length + 1];          // index = frequency
    foreach (var (x, f) in count) (buckets[f] ??= new List<int>()).Add(x);
    var res = new List<int>(k);
    for (int f = nums.Length; f > 0 && res.Count < k; f--)
        if (buckets[f] != null)
            foreach (int x in buckets[f]) {
                if (res.Count == k) break;
                res.Add(x);
            }
    return res.ToArray();
}

