public int[][] KClosest(int[][] points, int k) {
    var desc = Comparer<int>.Create((a, b) => b.CompareTo(a));
    var heap = new PriorityQueue<int[], int>(desc);   // max-heap by distance
    foreach (var p in points) {
        int d = p[0] * p[0] + p[1] * p[1];           // the square: ≤ 2·10⁸, fits in int
        heap.Enqueue(p, d);
        if (heap.Count > k) heap.Dequeue();          // the farthest one leaves
    }
    var res = new int[k][];
    for (int i = 0; i < k; i++) res[i] = heap.Dequeue();
    return res;
}

