// the k nearest to p: the buffer is sorted by squared distance
int Nearest(Vector3 p, List<Enemy> enemies, Enemy[] best, float[] bestD) {
    int k = best.Length, count = 0;
    foreach (var e in enemies) {
        float d = (e.Position - p).sqrMagnitude;            // no square root; Position is a cached position
        if (count == k && d >= bestD[k - 1]) continue;      // no better than the worst of the best
        int i = count < k ? count++ : k - 1;                // at the end or in place of the worst
        while (i > 0 && bestD[i - 1] > d) { best[i] = best[i - 1]; bestD[i] = bestD[i - 1]; i--; }
        best[i] = e; bestD[i] = d;
    }
    return count;                                           // found min(k, n)
}
